import{_ as e,C as n,c as i,o as t,j as r,G as a,a0 as s,b as l,a as o,w as h,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Workshop: Fortgeschrittenes Mentaltraining (3-4 Stunden)","description":"","frontmatter":{},"headers":[],"relativePath":"de/workshop.md","filePath":"de/workshop.md"}');const g=e({name:"de/workshop.md"},[["render",function(e,u,g,c,m,b){const p=n("AdBanner"),k=n("Mermaid"),f=n("AdInArticle");return t(),i("div",null,[u[4]||(u[4]=r("h1",{id:"workshop-fortgeschrittenes-mentaltraining-3-4-stunden",tabindex:"-1"},[o("Workshop: Fortgeschrittenes Mentaltraining (3-4 Stunden) "),r("a",{class:"header-anchor",href:"#workshop-fortgeschrittenes-mentaltraining-3-4-stunden","aria-label":'Permalink to "Workshop: Fortgeschrittenes Mentaltraining (3-4 Stunden)"'},"​")],-1)),a(p),u[5]||(u[5]=s('<h2 id="uberblick" tabindex="-1">Überblick <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Überblick&quot;">​</a></h2><p>Dieser Workshop ist ein fortgeschrittenes, 3- bis 4-stündiges Theorieseminar für 6 bis 8 Spitzenspieler, das sich auf tiefgreifende psychologische Arbeit und das Lernen aus der Auseinandersetzung mit Verletzlichkeit konzentriert. Er geht über grundlegende mentale Fähigkeiten hinaus und erforscht das innere Spiel auf einer tiefgreifenden Ebene.</p><div class="tip custom-block"><p class="custom-block-title">Dieser Leitfaden enthält zwei Abschnitte.</p><ul><li><strong><a href="#for-participants">Für Teilnehmer</a></strong> – Was die Spieler erleben und lernen werden</li><li><strong><a href="#for-facilitators">Für Moderatoren</a></strong> – Wie Sie als Koordinator für mentale Leistungsfähigkeit den Workshop durchführen</li></ul></div><p><strong>Unterschiede zur Anfängersitzung:</strong></p><ul><li><strong>Anfänger (2-3 Std.):</strong> Einführung in die Konzepte des mentalen Trainings → <a href="/en/mental-journey/session-guide">Siehe Mental Journey Guide</a></li><li><strong>Fortgeschritten (3-4 Std.):</strong> Tiefgehende psychologische Arbeit mit Übungen zur Verletzlichkeit (diese Seite)</li></ul><h2 id="schnellzugriff" tabindex="-1">Schnellzugriff <a class="header-anchor" href="#schnellzugriff" aria-label="Permalink to &quot;Schnellzugriff&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Abschnitt</th><th>Zweck</th><th>Zugang</th></tr></thead><tbody><tr><td><strong>Für Teilnehmer</strong></td><td>Was Sie erwartet und wie Sie sich vorbereiten können</td><td><a href="#for-participants">Abschnitt anzeigen</a></td></tr><tr><td><strong>Für Moderatoren</strong></td><td>Vollständiger Sitzungsleitfaden und Übungen</td><td><a href="#for-facilitators">Abschnitt anzeigen</a></td></tr><tr><td><strong>Sitzungsmaterialien</strong></td><td>Übungen und Arbeitsblätter</td><td><a href="#facilitator-materials">Materialien ansehen</a></td></tr><tr><td><strong>Verwandte Leitfäden</strong></td><td>Andere Trainingsformate</td><td><a href="/en/mental-journey/">Mentale Reise</a> • <a href="/en/training-camp">Trainingslager</a></td></tr></tbody></table><hr><h2 id="fur-teilnehmer" tabindex="-1">Für Teilnehmer <a class="header-anchor" href="#fur-teilnehmer" aria-label="Permalink to &quot;Für Teilnehmer&quot;">​</a></h2><h3 id="was-sie-erwartet" tabindex="-1">Was Sie erwartet <a class="header-anchor" href="#was-sie-erwartet" aria-label="Permalink to &quot;Was Sie erwartet&quot;">​</a></h3><p>Dies ist kein typisches Training. Sie werden sich intensiv mit den mentalen und emotionalen Aspekten des Pétanque auseinandersetzen, über die selten offen gesprochen wird.</p><p><strong>Dieser Workshop ist:</strong></p><ul><li>✅ Ein sicherer Raum, um innere Gedanken und Ängste zu erforschen</li><li>✅ Lernen auf Basis von Verletzlichkeit mit Teammitgliedern</li><li>✅ Zusammenhang zwischen mentalen Mustern und Leistung</li><li>✅ Aufbau psychologischer Intelligenz im Team</li></ul><p><strong>Dieser Workshop ist NICHT:</strong></p><ul><li>❌ Technisches Coaching oder Taktiktraining</li><li>❌ Therapie oder Beratung</li><li>❌ Reden zum positiven Denken oder zur Motivation</li><li>❌ Urteil oder Kritik</li></ul><h3 id="sitzungsstruktur" tabindex="-1">Sitzungsstruktur <a class="header-anchor" href="#sitzungsstruktur" aria-label="Permalink to &quot;Sitzungsstruktur&quot;">​</a></h3>',16)),(t(),l(d,null,{default:h(()=>[a(k,{id:"mermaid-167",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWorkshop-Sitzung%5D%20--%3E%20B%5BGrundlagen%2060%20Minuten%5D%0A%20%20%20%20B%20--%3E%20C%5BTiefenarbeit%2090%20Minuten%5D%0A%20%20%20%20C%20--%3E%20D%5BIntegration%2045%20Minuten%5D%0A%20%20%20%20D%20--%3E%20E%5BSchlie%C3%9Fung%2015%20Minuten%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23ffe4e1%0A%20%20%20%20style%20D%20fill%3A%23e3f2fd%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:h(()=>[...u[0]||(u[0]=[o(" Loading... ",-1)])]),_:1})),u[6]||(u[6]=s('<p><strong>Gesamtdauer:</strong> 3-4 Stunden <strong>Gruppengröße:</strong> 6-8 Spieler <strong>Format:</strong> Gesprächsrunde mit strukturierten Übungen</p><h3 id="was-sie-lernen-werden" tabindex="-1">Was Sie lernen werden <a class="header-anchor" href="#was-sie-lernen-werden" aria-label="Permalink to &quot;Was Sie lernen werden&quot;">​</a></h3><h4 id="phase-1-grundlagen-60-min" tabindex="-1">Phase 1: Grundlagen (60 Min.) <a class="header-anchor" href="#phase-1-grundlagen-60-min" aria-label="Permalink to &quot;Phase 1: Grundlagen (60 Min.)&quot;">​</a></h4><ul><li>Grundregeln für psychologische Sicherheit</li><li>Die &quot;Check-in-Matrix&quot; – Bestätigung Ihres aktuellen Zustands</li><li>Der „Eisberg des Boule“ – verborgene Gedanken entdecken</li></ul><h4 id="phase-2-konzentriertes-arbeiten-90-min" tabindex="-1">Phase 2: Konzentriertes Arbeiten (90 Min.) <a class="header-anchor" href="#phase-2-konzentriertes-arbeiten-90-min" aria-label="Permalink to &quot;Phase 2: Konzentriertes Arbeiten (90 Min.)&quot;">​</a></h4><ul><li>Erstellen Sie Ihr &quot;Benutzerhandbuch&quot; für Teammitglieder</li><li>Zusammenhang zwischen mentalen Mustern und Leistung</li><li>„Angst mit Hut“ – Isolation durch geteilte Verletzlichkeit überwinden</li></ul><h4 id="phase-3-integration-45-min" tabindex="-1">Phase 3: Integration (45 Min.) <a class="header-anchor" href="#phase-3-integration-45-min" aria-label="Permalink to &quot;Phase 3: Integration (45 Min.)&quot;">​</a></h4><ul><li>Den inneren Kritiker in einen inneren Coach verwandeln</li><li>Erstellung von Teamprotokollen für den Wettbewerb</li><li>Praktische Tipps für die Piste</li></ul><h4 id="phase-4-abschluss-15-min" tabindex="-1">Phase 4: Abschluss (15 Min.) <a class="header-anchor" href="#phase-4-abschluss-15-min" aria-label="Permalink to &quot;Phase 4: Abschluss (15 Min.)&quot;">​</a></h4><ul><li>Reflexion und Engagement</li><li>Nachbetreuung</li></ul><h3 id="grundregeln" tabindex="-1">Grundregeln <a class="header-anchor" href="#grundregeln" aria-label="Permalink to &quot;Grundregeln&quot;">​</a></h3><p>Vor Beginn der Sitzung erklären sich alle Teilnehmer mit Folgendem einverstanden:</p><div class="tip custom-block"><p class="custom-block-title">Der Container – Wesentliche Grundregeln</p><ol><li><strong>Vertraulichkeit</strong> – Was hier gesagt wird, bleibt hier.</li><li><strong>Die Vegas-Regel</strong> – Lektionen verlassen den Raum, Geschichten bleiben.</li><li><strong>Keine Reparaturversuche</strong> – Beobachten und verstehen, nicht versuchen, das Problem zu lösen.</li><li><strong>Recht auf Weiterkommen</strong> – Schutzbedürftigkeit darf nicht erzwungen werden</li><li><strong>Respektiere den Prozess</strong> – Vertraue dem Unbehagen.</li></ol></div><h3 id="was-sie-mitbringen-sollten" tabindex="-1">Was Sie mitbringen sollten <a class="header-anchor" href="#was-sie-mitbringen-sollten" aria-label="Permalink to &quot;Was Sie mitbringen sollten&quot;">​</a></h3><p><strong>Erforderlich:</strong></p><ul><li>Offenheit und Bereitschaft zum Teilen</li><li>Ihre eigenen Erfahrungen und Herausforderungen</li><li>Respekt vor der Verletzlichkeit anderer</li></ul><p><strong>Optional:</strong></p><ul><li>Notizbuch für persönliche Reflexionen</li><li>Fragen zu spezifischen mentalen Herausforderungen</li></ul><h3 id="wichtigste-aktivitaten-die-sie-erleben-werden" tabindex="-1">Wichtigste Aktivitäten, die Sie erleben werden <a class="header-anchor" href="#wichtigste-aktivitaten-die-sie-erleben-werden" aria-label="Permalink to &quot;Wichtigste Aktivitäten, die Sie erleben werden&quot;">​</a></h3><h4 id="die-check-in-matrix" tabindex="-1">Die Check-in-Matrix <a class="header-anchor" href="#die-check-in-matrix" aria-label="Permalink to &quot;Die Check-in-Matrix&quot;">​</a></h4><p>Ordne dich in ein Raster aus Energie und Stimmung ein. Akzeptiere, dass wir alle unterschiedliche Zustände haben.</p><h4 id="der-eisberg-des-boule" tabindex="-1">Der Eisberg des Boule <a class="header-anchor" href="#der-eisberg-des-boule" aria-label="Permalink to &quot;Der Eisberg des Boule&quot;">​</a></h4><p>Erforsche, was unter der Oberfläche vor sich geht – die Gedanken und Ängste, die niemand sieht.</p><h4 id="benutzerhandbuch" tabindex="-1">Benutzerhandbuch <a class="header-anchor" href="#benutzerhandbuch" aria-label="Permalink to &quot;Benutzerhandbuch&quot;">​</a></h4><p>Erstellen Sie eine Bedienungsanleitung für sich selbst, damit Ihre Teamkollegen wissen, wie sie Sie unterstützen können.</p><h4 id="angst-im-hut" tabindex="-1">Angst im Hut <a class="header-anchor" href="#angst-im-hut" aria-label="Permalink to &quot;Angst im Hut&quot;">​</a></h4><p>Teile anonym deine tiefsten Ängste und erhalte Bestätigung von Gleichgesinnten. Durchbrich die Isolation.</p><h4 id="umdeutung-des-inneren-kritikers" tabindex="-1">Umdeutung des inneren Kritikers <a class="header-anchor" href="#umdeutung-des-inneren-kritikers" aria-label="Permalink to &quot;Umdeutung des inneren Kritikers&quot;">​</a></h4><p>Verwandle harsche Selbstgespräche in unterstützende Coaching-Sprache.</p><h3 id="nach-dem-workshop" tabindex="-1">Nach dem Workshop <a class="header-anchor" href="#nach-dem-workshop" aria-label="Permalink to &quot;Nach dem Workshop&quot;">​</a></h3><p>Sie werden mitnehmen:</p><ul><li>Ein tieferes Verständnis Ihrer mentalen Muster</li><li>Teamprotokolle zur gegenseitigen Unterstützung</li><li>Umformulierte Formulierungen des Inneren Coaches</li><li>Verbindung zu Teammitgliedern durch geteilte Verletzlichkeit</li><li>Praktische Instrumente für den Wettbewerb</li></ul><div class="warning custom-block"><p class="custom-block-title">Nachwirkungen der Sicherheitslücke</p><p>Nach einem so offenen Austausch fühlen Sie sich vielleicht verletzlich oder bereuen es. Das ist normal. Die Moderatorin/Der Moderator meldet sich innerhalb von 24 Stunden bei Ihnen. Denken Sie daran: Was Sie geteilt haben, hat allen geholfen.</p></div>',33)),a(f),u[7]||(u[7]=s('<hr><h2 id="fur-moderatoren" tabindex="-1">Für Moderatoren <a class="header-anchor" href="#fur-moderatoren" aria-label="Permalink to &quot;Für Moderatoren&quot;">​</a></h2><h3 id="ihre-rolle-als-koordinator-fur-mentale-leistungsfahigkeit" tabindex="-1">Ihre Rolle als Koordinator für mentale Leistungsfähigkeit <a class="header-anchor" href="#ihre-rolle-als-koordinator-fur-mentale-leistungsfahigkeit" aria-label="Permalink to &quot;Ihre Rolle als Koordinator für mentale Leistungsfähigkeit&quot;">​</a></h3><p>Als <strong>Mental Performance Coordinator (MPC)</strong> moderieren Sie intensive Gespräche über die mentale Komponente des Sports und schaffen so eine psychologische Sicherheit, die sich positiv auf die Leistung auf der Piste auswirkt.</p><div class="warning custom-block"><p class="custom-block-title">Kritisches Konzept</p><p><strong>Sie sind kein technischer Trainer oder Therapeut.</strong> Ihre Rolle besteht darin, ein auf Verletzlichkeit basierendes Lernverfahren zu fördern, das den Spielern hilft, den Zusammenhang zwischen ihren inneren Gedanken und ihrer Leistung zu verstehen.</p></div><h3 id="ihre-verantwortlichkeiten" tabindex="-1">Ihre Verantwortlichkeiten <a class="header-anchor" href="#ihre-verantwortlichkeiten" aria-label="Permalink to &quot;Ihre Verantwortlichkeiten&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Hauptverantwortlichkeiten</p><ul><li><strong>Moderieren statt belehren</strong> – Sie leiten die Diskussion, nicht die Technik.</li><li><strong>Raum schaffen</strong> – Psychologische Sicherheit schaffen und erhalten</li><li><strong>Theorie und Praxis verbinden</strong> – Website-Inhalte mit inneren Erfahrungen verknüpfen</li><li><strong>Gruppendynamik beobachten</strong> – Achten Sie darauf, wer sich beteiligt und wer Widerstand leistet.</li><li><strong>Grenzen wahren</strong> – Wissen, wann professionelle Hilfe angebracht ist</li></ul></div><h3 id="vorbereitung-auf-den-workshop" tabindex="-1">Vorbereitung auf den Workshop <a class="header-anchor" href="#vorbereitung-auf-den-workshop" aria-label="Permalink to &quot;Vorbereitung auf den Workshop&quot;">​</a></h3><h3 id="wesentliche-kompetenzen" tabindex="-1">Wesentliche Kompetenzen <a class="header-anchor" href="#wesentliche-kompetenzen" aria-label="Permalink to &quot;Wesentliche Kompetenzen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kompetenz</th><th>Was es bedeutet</th><th>Wie man entwickelt</th></tr></thead><tbody><tr><td><strong>Emotionale Intelligenz</strong></td><td>Mikroexpressionen des Unbehagens erkennen</td><td>Aktive Beobachtung üben</td></tr><tr><td><strong>Neutrale Autorität</strong></td><td>Respekt erlangen ohne technische Macht</td><td>Schaffen Sie Glaubwürdigkeit durch Präsenz</td></tr><tr><td><strong>Sportkontext</strong></td><td>Druckmechanik verstehen</td><td>Lerne die Fachbegriffe und die Kultur des Pétanque kennen.</td></tr><tr><td><strong>Verbales Aikido</strong></td><td>Verbünde dich mit dem Widerstand, bekämpfe ihn nicht.</td><td>Üben Sie eine nicht-defensive Kommunikation</td></tr></tbody></table><details class="details custom-block"><summary>Wichtige Pétanque-Begriffe, die man kennen sollte</summary><ul><li><strong>Carreau</strong> – Ein perfekter Stoß, der die Boule des Gegners verdrängt.</li><li><strong>Bibber</strong> – Das „Jauchzen“ – unwillkürliches Zittern während der Freisetzung</li><li><strong>Donnée</strong> – Das „Gegebene“ – das Terrain so akzeptieren, wie es ist</li><li><strong>Portée</strong> - Werfen ohne Aufprall</li><li><strong>Roulette</strong> - Rollender Schuss</li><li><strong>Cochonnet</strong> - Die Zielkugel (Jack)</li></ul></details><h2 id="physischer-aufbau-der-magische-kreis" tabindex="-1">Physischer Aufbau: Der magische Kreis <a class="header-anchor" href="#physischer-aufbau-der-magische-kreis" aria-label="Permalink to &quot;Physischer Aufbau: Der magische Kreis&quot;">​</a></h2><h3 id="standortanforderungen" tabindex="-1">Standortanforderungen <a class="header-anchor" href="#standortanforderungen" aria-label="Permalink to &quot;Standortanforderungen&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Kritische Einrichtung</p><p><strong>Wählen Sie einen neutralen Ort abseits der Piste.</strong> Dies signalisiert einen Wechsel von körperlicher zu geistiger Arbeit.</p><p>Anforderungen:</p><ul><li>✅ Schalldicht oder privat</li><li>✅ Angenehme Temperatur</li><li>✅ Keine Ablenkungen (Handys aus)</li><li>✅ Wenn möglich, natürliches Licht.</li><li>✅ Vom Trainingsbereich getrennt</li></ul></div><h3 id="die-kreiskonfiguration" tabindex="-1">Die Kreiskonfiguration <a class="header-anchor" href="#die-kreiskonfiguration" aria-label="Permalink to &quot;Die Kreiskonfiguration&quot;">​</a></h3><p><strong>Sitzplätze:</strong></p><ul><li>Ein perfekter Stuhlkreis</li><li><strong>KEINE TISCHE</strong> – Tische schaffen Barrieren und verdecken die Körpersprache.</li><li>Alle Stühle auf gleicher Höhe (keine elektrischen Verstellmöglichkeiten)</li><li>Der Koordinator sitzt im Kreis (nicht vorne).</li></ul><p><strong>Zentrumsobjekte:</strong></p><ul><li>Kugeln und Cochonnet in die Mitte legen</li><li>Verankert die Arbeit im Sport</li><li>Visuelle Erinnerung an das gemeinsame Ziel</li></ul>',19)),(t(),l(d,null,{default:h(()=>[a(k,{id:"mermaid-632",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BPhysischer%20Raum%5D%20--%3E%20B%5BSignale%20f%C3%BCr%20einen%20mentalen%20Wandel%5D%0A%20%20%20%20A%20--%3E%20C%5BKeine%20Barrieren%5D%0A%20%20%20%20A%20--%3E%20D%5BGleiche%20Positionierung%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BPsychologische%20Sicherheit%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:h(()=>[...u[1]||(u[1]=[o(" Loading... ",-1)])]),_:1})),u[8]||(u[8]=s('<h2 id="sitzungsstruktur-3-4-stunden" tabindex="-1">Sitzungsstruktur (3-4 Stunden) <a class="header-anchor" href="#sitzungsstruktur-3-4-stunden" aria-label="Permalink to &quot;Sitzungsstruktur (3-4 Stunden)&quot;">​</a></h2><h3 id="phase-1-grundlagen-60-minuten" tabindex="-1">Phase 1: Grundlagen (60 Minuten) <a class="header-anchor" href="#phase-1-grundlagen-60-minuten" aria-label="Permalink to &quot;Phase 1: Grundlagen (60 Minuten)&quot;">​</a></h3><h4 id="_1-begrußung-amp-grundregeln-15-min" tabindex="-1">1. Begrüßung &amp; Grundregeln (15 Min.) <a class="header-anchor" href="#_1-begrußung-amp-grundregeln-15-min" aria-label="Permalink to &quot;1. Begrüßung &amp;amp; Grundregeln (15 Min.)&quot;">​</a></h4><p><strong>Der Gesellschaftsvertrag:</strong></p><div class="tip custom-block"><p class="custom-block-title">Der Container – Wesentliche Grundregeln</p><p>Bevor die Weitergabe von Informationen beginnt, muss die Gruppe Folgendem zustimmen:</p><ol><li><strong>Vertraulichkeit</strong> – Was hier gesagt wird, bleibt hier.</li><li><strong>Die Vegas-Regel</strong> – Lektionen verlassen den Raum, Geschichten bleiben.</li><li><strong>Keine Reparaturversuche</strong> – Beobachten und verstehen, nicht versuchen, das Problem zu lösen.</li><li><strong>Recht auf Weiterkommen</strong> – Schutzbedürftigkeit darf nicht erzwungen werden</li><li><strong>Respektiere den Prozess</strong> – Vertraue dem Unbehagen.</li></ol></div><p><strong>Ihr Skript:</strong></p><blockquote><p>„Willkommen. Dieser Raum ist anders als die Piste. Hier erforschen wir, was <em>in dir</em> vorgeht, wenn du am Abschlag stehst. Alles, was du hier teilst, ist vertraulich. Die gewonnenen Erkenntnisse kannst du mitnehmen, aber die persönlichen Geschichten bleiben. Ihr seid nicht hier, um einander zu verändern – sondern um einander zu verstehen. Und ihr könnt jederzeit passen. Sind alle damit einverstanden?“</p></blockquote><h4 id="_2-aktivitat-die-check-in-matrix-20-min" tabindex="-1">2. Aktivität: Die Check-in-Matrix (20 Min.) <a class="header-anchor" href="#_2-aktivitat-die-check-in-matrix-20-min" aria-label="Permalink to &quot;2. Aktivität: Die Check-in-Matrix (20 Min.)&quot;">​</a></h4><p><strong>Ziel:</strong> Das Eingeständnis von Müdigkeit oder Stress normalisieren</p><p><strong>Materialien:</strong> Whiteboard oder Flipchart, Haftnotizen</p><p><strong>Verfahren:</strong></p><ol><li>Zeichne eine 2x2-Matrix: Hohe/Niedrige Energie (vertikal), Positiv/Negativ (horizontal)</li><li>Jeder Spieler schreibt seinen Namen auf einen Haftzettel.</li><li>Platzieren Sie die Notiz in ihrem aktuellen Quadranten.</li><li>Diskussion: „Wir haben drei Personen in der Kategorie ‚Niedrige Energie/Negativ‘. Wie wirkt sich das auf unsere heutige Sitzung aus?“</li></ol>',12)),(t(),l(d,null,{default:h(()=>[a(k,{id:"mermaid-719",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BCheck-in-Matrix%5D%20--%3E%20B%5BHohe%20Energie%20%2B%20Positiv%5D%0A%20%20%20%20A%20--%3E%20C%5BHohe%20Energie%20%2B%20Negativ%5D%0A%20%20%20%20A%20--%3E%20D%5BNiedrige%20Energie%20%2B%20Positiv%5D%0A%20%20%20%20A%20--%3E%20E%5BNiedrige%20Energie%20%2B%20Negativ%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BAnerkennung%20aller%20Staaten%5D%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20D%20--%3E%20F%0A%20%20%20%20E%20--%3E%20F%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:h(()=>[...u[2]||(u[2]=[o(" Loading... ",-1)])]),_:1})),u[9]||(u[9]=s('<p><strong>Tipps zur Moderation:</strong></p><ul><li>Beurteilen Sie keinen Quadranten als &quot;schlecht&quot;.</li><li>Frage: „Was braucht dein Körper jetzt gerade?“</li><li>Muster erkennen: „Ihr drei seid im selben Raum – was hat das zu bedeuten?“</li></ul><h4 id="_3-aktivitat-der-eisberg-des-boule-25-min" tabindex="-1">3. Aktivität: Der Eisberg des Boule (25 Min.) <a class="header-anchor" href="#_3-aktivitat-der-eisberg-des-boule-25-min" aria-label="Permalink to &quot;3. Aktivität: Der Eisberg des Boule (25 Min.)&quot;">​</a></h4><p><strong>Ziel:</strong> Verborgene innere Gedanken visualisieren</p><p><strong>Materialien:</strong> Großes Papier, Filzstifte</p><p><strong>Verfahren:</strong></p><ol><li>Zeichne einen Eisberg auf Papier</li><li><strong>Über Wasser:</strong> Schreiben Sie „Technik, Wurf, Ergebnis“ auf.</li><li><strong>Unter Wasser:</strong> Frage: &quot;Was geht in deinem Kopf vor, das niemand sieht?&quot;</li></ol><p><strong>Aufgaben:</strong></p><ul><li>„Wovor hast du Angst, wenn du zum Schuss antrittst?“</li><li>„Vor welchem Urteil haben Sie Angst?“</li><li>„Was sagt deine innere Stimme, wenn du daneben schießt?“</li></ul><p><strong>Die Erkenntnisfrage:</strong></p><blockquote><p>„Was passiert mit Ihrem Wurfarm, wenn die Unterwasser-Ausrüstung zu schwer wird?“</p></blockquote><p>Dies stellt einen Zusammenhang zwischen mentaler Belastung und körperlicher Anspannung her (dem Bibber-/Jauchzer-Syndrom).</p><details class="details custom-block"><summary>Häufige Reaktionen im Kontext von „Unter Wasser“</summary><ul><li>Angst, das Team im Stich zu lassen</li><li>Mach dir keine Sorgen, dumm auszusehen.</li><li>Zweifel an der Fähigkeit</li><li>Vergleich mit anderen</li><li>Druck, seinen Wert zu beweisen</li><li>Angst vor der Verurteilung durch Trainer/Teamkollegen</li><li>Hochstapler-Syndrom</li></ul></details>',13)),a(f),u[10]||(u[10]=s('<h3 id="phase-2-konzentriertes-arbeiten-90-minuten" tabindex="-1">Phase 2: Konzentriertes Arbeiten (90 Minuten) <a class="header-anchor" href="#phase-2-konzentriertes-arbeiten-90-minuten" aria-label="Permalink to &quot;Phase 2: Konzentriertes Arbeiten (90 Minuten)&quot;">​</a></h3><h4 id="_4-aktivitat-das-benutzerhandbuch-30-min" tabindex="-1">4. Aktivität: Das Benutzerhandbuch (30 Min.) <a class="header-anchor" href="#_4-aktivitat-das-benutzerhandbuch-30-min" aria-label="Permalink to &quot;4. Aktivität: Das Benutzerhandbuch (30 Min.)&quot;">​</a></h4><p><strong>Ziel:</strong> Empathie in die Praxis umsetzen – Teammitgliedern helfen, einander zu verstehen</p><p><strong>Materialien:</strong> Arbeitsblätter (eines pro Spieler)</p><p><strong>Vorlage für das Benutzerhandbuch:</strong></p><table tabindex="0"><thead><tr><th>Abschnitt</th><th>Prompt</th><th>Beispiel</th></tr></thead><tbody><tr><td><strong>Meine Stresssignatur</strong></td><td>„Wenn ich ängstlich bin, dann…“</td><td>&quot;...völlig still werden&quot;</td></tr><tr><td><strong>Wie man mit mir umgeht</strong></td><td>„Wenn ich einen entscheidenden Schuss verpasse, brauche ich...“</td><td>„…Schweigen statt Ermutigung“</td></tr><tr><td><strong>Meine inneren Gedanken</strong></td><td>„Die Lüge, die ich mir selbst erzähle, ist…“</td><td>&quot;...dass ich nicht gut genug bin&quot;</td></tr><tr><td><strong>Mein Trigger</strong></td><td>„Ich reagiere defensiv, wenn…“</td><td>&quot;...jemand stellt meine Schusswahl in Frage&quot;</td></tr></tbody></table><p><strong>Verfahren:</strong></p><ol><li>Geben Sie den Spielern 10 Minuten Zeit, um die Aufgabe in Stille zu lösen.</li><li>Im Kreis herum – jede Person teilt sich EINEN Abschnitt.</li><li>Andere können klärende Fragen stellen (keine Ratschläge!).</li><li>Der Koordinator prüft jeden Anteil.</li></ol><p><strong>Moderationsskript:</strong></p><blockquote><p>„Das ist eure Bedienungsanleitung. Wenn eure Teamkollegen wissen, dass ihr in stressigen Situationen still werdet, nehmen sie es euch nicht übel. Wenn sie wissen, dass ihr nach einem Fehlschlag Ruhe braucht, versuchen sie nicht, euch zu ‚reparieren‘. So fördern wir die Teamintelligenz.“</p></blockquote><h4 id="_5-verbindung-von-website-inhalten-mit-inneren-gedanken-30-min" tabindex="-1">5. Verbindung von Website-Inhalten mit inneren Gedanken (30 Min.) <a class="header-anchor" href="#_5-verbindung-von-website-inhalten-mit-inneren-gedanken-30-min" aria-label="Permalink to &quot;5. Verbindung von Website-Inhalten mit inneren Gedanken (30 Min.)&quot;">​</a></h4><p><strong>Ziel:</strong> Technische Inhalte mit psychologischen Erfahrungen verknüpfen</p><p>Wählen Sie 2-3 Abschnitte von der Website der Akademie aus und erkunden Sie das innere Spiel:</p><p><strong>Beispiel 1: Technik – Der Griff und das Loslassen</strong></p><p><strong>Die Vertrauensfrage:</strong></p><blockquote><p>&quot;Wenn du in einem Turnier bei 12:12 stehst, fühlt sich deine Hand dann so an, wie es in der Technikbeschreibung beschrieben ist? Sind es die Muskeln, die sich verändern, oder der Gedanke &#39;Lass den Ball nicht fallen&#39;, der deinen Griff verändert?&quot;</p></blockquote><p><strong>Das Mikrobeben:</strong></p><blockquote><p>Wer von Ihnen spürt das „Mikrozittern“ der Angst? Welcher innere Gedanke löst das aus?</p></blockquote><p><strong>Beispiel 2: Taktik – Zeigen vs. Schießen</strong></p><p><strong>Risikoprofil:</strong></p><blockquote><p>„Wenn im Leitfaden steht ‚Schießen Sie auf Sieg‘, reagieren Sie dann mit Begeisterung oder mit Furcht? Was sagt das über Ihr Verhältnis zum Risiko aus?“</p></blockquote><p><strong>Der Betrüger:</strong></p><blockquote><p>&quot;Zeigst du jemals auf etwas, obwohl du <em>weißt</em>, dass du schießen solltest, nur um die Peinlichkeit eines Fehlschusses zu vermeiden? Was kostet diese Sicherheit?&quot;</p></blockquote><p><strong>Beispiel 3: Ernährung – Wettkampftag</strong></p><p><strong>Die Komfortessen-Falle:</strong></p><blockquote><p>„Isst du, was dein Körper braucht oder was deine Angst verlangt? Woher weißt du den Unterschied?“</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Moderationstechnik</p><p>Halten Sie keine Vorträge über den Inhalt. Stellen Sie Fragen, die die technischen Informationen mit ihren Lebenserfahrungen verknüpfen. Die Erkenntnisse kommen von ihnen, nicht von Ihnen.</p></div><h4 id="_6-aktivitat-angst-im-hut-30-min" tabindex="-1">6. Aktivität: Angst im Hut (30 Min.) <a class="header-anchor" href="#_6-aktivitat-angst-im-hut-30-min" aria-label="Permalink to &quot;6. Aktivität: Angst im Hut (30 Min.)&quot;">​</a></h4><p><strong>Ziel:</strong> Den Isolationskreislauf durchbrechen – zeigen, dass Gleichaltrige ähnliche tiefe Unsicherheiten haben</p><p><strong>Materialien:</strong> Papier, Stift, Hut/Tasche</p><p><strong>Verfahren:</strong></p><ol><li>Jeder schreibt anonym über eine tiefgreifende Karriere-/Teamangst.</li><li>Papier falten und mit Hut vermischen</li><li>Jeder Spieler zeichnet eine Note (nicht seine eigene).</li><li>Lies es laut vor</li><li>Bestätigen Sie es: „Ich kann verstehen, warum jemand so empfindet, denn…“</li></ol><p><strong>Beispielhafte Ängste:</strong></p><ul><li>„Ich fürchte, ich habe meinen Leistungszenit erreicht und werde mich nie wieder verbessern.“</li><li>„Ich mache mir Sorgen, dass meine Teamkollegen mich für überschätzt halten.“</li><li>&quot;Ich fürchte, ich werde im entscheidenden Moment versagen.&quot;</li><li>&quot;Ich habe Angst, von jüngeren Spielern ersetzt zu werden.&quot;</li></ul><p><strong>Die Kraft:</strong> Wenn Spieler ihre geheime Angst laut vorgelesen und von Gleichaltrigen bestätigt hören, löst sich die Scham auf. Sie erkennen: „Ich bin nicht allein. Das ist normal.“</p><p><strong>Rolle des Koordinators/der Koordinatorin:</strong></p><ul><li>Bestätige JEDE Angst als berechtigt.</li><li>Verharmlosen Sie nicht: „Das stimmt nicht!“ entwertet das Gefühl.</li><li>Frage: „Wie viele von Ihnen haben etwas Ähnliches empfunden?“</li></ul>',37)),(t(),l(d,null,{default:h(()=>[a(k,{id:"mermaid-1100",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BAngst%20im%20Hut%5D%20--%3E%20B%5BAnonymes%20Teilen%5D%0A%20%20%20%20B%20--%3E%20C%5BPeer-Validierung%5D%0A%20%20%20%20C%20--%3E%20D%5BScham%20l%C3%B6st%20sich%20auf%5D%0A%20%20%20%20D%20--%3E%20E%5BIsolationspausen%5D%0A%20%20%20%20E%20--%3E%20F%5BPsychologische%20Sicherheit%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffe4e1%0A%20%20%20%20style%20F%20fill%3A%23e8f5e9%0A"})]),fallback:h(()=>[...u[3]||(u[3]=[o(" Loading... ",-1)])]),_:1})),u[11]||(u[11]=s('<h3 id="phase-3-integration-45-minuten" tabindex="-1">Phase 3: Integration (45 Minuten) <a class="header-anchor" href="#phase-3-integration-45-minuten" aria-label="Permalink to &quot;Phase 3: Integration (45 Minuten)&quot;">​</a></h3><h4 id="_7-aktivitat-den-inneren-kritiker-neu-definieren-25-min" tabindex="-1">7. Aktivität: Den inneren Kritiker neu definieren (25 Min.) <a class="header-anchor" href="#_7-aktivitat-den-inneren-kritiker-neu-definieren-25-min" aria-label="Permalink to &quot;7. Aktivität: Den inneren Kritiker neu definieren (25 Min.)&quot;">​</a></h4><p><strong>Ziel:</strong> Kognitive Umstrukturierung – Veränderung des inneren Dialogs</p><p><strong>Materialien:</strong> Arbeitsblatt</p><p><strong>Verfahren:</strong></p><p><strong>Schritt 1: Den Kritiker identifizieren (10 Min.)</strong></p><blockquote><p>„Schreiben Sie genau den Satz auf, den Ihr innerer Kritiker nach einem Fehler von sich gibt. Nicht die höfliche Version – sondern die brutale.“</p></blockquote><p>Beispiele:</p><ul><li>&quot;Du versagst immer.&quot;</li><li>&quot;Alle sehen dir beim Scheitern zu.&quot;</li><li>&quot;Du blamierst dich.&quot;</li><li>&quot;Du gehörst hier nicht hin.&quot;</li></ul><p><strong>Schritt 2: Die Perspektive des inneren Coaches einnehmen (10 Min.)</strong></p><blockquote><p>„Schreibe das nun als deinen inneren Coach um – bestimmt, aber unterstützend.“</p></blockquote><p>Beispiele:</p><ul><li>Kritiker: „Du versagst immer.“ → Trainer: „Neustart und durchatmen. Nächster Versuch.“</li><li>Kritiker: „Alle sehen dir beim Scheitern zu.“ → Trainer: „Konzentriere dich auf das Ziel, nicht auf die Zuschauer.“</li><li>Kritiker: „Du blamierst dich.“ → Trainer: „Einen Versuch nach dem anderen. Du hast das schon einmal geschafft.“</li></ul><p><strong>Schritt 3: Partnerübung (5 Min.)</strong></p><blockquote><p>„Teilen Sie Ihren Coach-Satz mit einem Partner. Er wird Sie daran erinnern, wenn er den Kritiker in sich bemerkt.“</p></blockquote><h4 id="_8-brucke-zur-piste-20-min" tabindex="-1">8. Brücke zur Piste (20 Min.) <a class="header-anchor" href="#_8-brucke-zur-piste-20-min" aria-label="Permalink to &quot;8. Brücke zur Piste (20 Min.)&quot;">​</a></h4><p><strong>Ziel:</strong> Erstellung umsetzbarer Protokolle für den Wettbewerb</p><p><strong>Diskussionsfragen:</strong></p><ol><li>&quot;Was ist EINE Sache von heute, die du in deinem nächsten Wettkampf anwenden wirst?&quot;</li><li>„Woran werden deine Teamkollegen erkennen, dass du Unterstützung benötigst?“</li><li>„Was ist dein Signal für ‚Ich brauche eine mentale Auszeit‘?“</li></ol><p><strong>Teamprotokolle erstellen:</strong></p><table tabindex="0"><thead><tr><th>Situation</th><th>Protokoll</th><th>Beispiel</th></tr></thead><tbody><tr><td><strong>Nach einem Fehlschuss</strong></td><td>Siehe Benutzerhandbuch</td><td>„Marc braucht Ruhe, Lisa braucht einen Faustgruß.“</td></tr><tr><td><strong>Unter Druck stehen</strong></td><td>Verwenden Sie die Formulierung „Trainer“.</td><td>„Neustart und durchatmen“</td></tr><tr><td><strong>Spannungen im Team</strong></td><td>Anruf-Timeout</td><td>&quot;Nehmen wir uns 2 Minuten Zeit.&quot;</td></tr><tr><td><strong>Innerer Kritiker laut</strong></td><td>Physischer Reset</td><td>Boules berühren, tief durchatmen</td></tr></tbody></table><h3 id="phase-4-abschluss-15-minuten" tabindex="-1">Phase 4: Abschluss (15 Minuten) <a class="header-anchor" href="#phase-4-abschluss-15-minuten" aria-label="Permalink to &quot;Phase 4: Abschluss (15 Minuten)&quot;">​</a></h3><h4 id="_9-der-check-out-10-min" tabindex="-1">9. Der Check-out (10 Min.) <a class="header-anchor" href="#_9-der-check-out-10-min" aria-label="Permalink to &quot;9. Der Check-out (10 Min.)&quot;">​</a></h4><p><strong>Verfahren:</strong> Reihum erzählt jeder:</p><ol><li><strong>Eine Sache, die Sie mitnehmen:</strong> „Welche Erkenntnis oder welches Werkzeug nehmen Sie mit nach Hause?“</li><li><strong>Eines, das du zurücklässt:</strong> „Was lässt du los?“</li></ol><p><strong>Rolle des Koordinators/der Koordinatorin:</strong></p><ul><li>Vielen Dank an alle Beteiligten für ihren Beitrag.</li><li>Die geleistete Arbeit überprüfen</li><li>Erinnern Sie an die Vertraulichkeit</li></ul><h4 id="_10-nachfolgeprotokoll-5-min" tabindex="-1">10. Nachfolgeprotokoll (5 Min.) <a class="header-anchor" href="#_10-nachfolgeprotokoll-5-min" aria-label="Permalink to &quot;10. Nachfolgeprotokoll (5 Min.)&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Entscheidend: Sicherheitslücken vermeiden</p><p>Konzentriertes Arbeiten führt zu einem „Verletzlichkeitskater“ – Reue oder Scham über das Teilen der Erfahrung.</p><p><strong>Ihr 24-Stunden-Protokoll:</strong></p><ul><li>Schicke innerhalb von 24 Stunden eine Nachricht an alle, die den Beitrag häufig geteilt haben.</li><li>Nachricht: „Vielen Dank für Ihren Mut gestern. Was Sie mitgeteilt haben, hat allen geholfen.“</li><li>Nachfrage: „Wie empfinden Sie die Sitzung?“</li></ul></div><p><strong>Abschlussskript:</strong></p><blockquote><p>„Was heute hier geschah, erforderte Mut. Ihr seid gekommen, ihr habt euch geöffnet, ihr habt dem Prozess vertraut. Denselben Mut werdet ihr auch auf die Piste mitbringen. Denkt daran: Die Lektionen verlassen diesen Raum, aber die Geschichten bleiben. Danke.“</p></blockquote>',31)),a(f),u[12]||(u[12]=s('<h2 id="handhabungswiderstand" tabindex="-1">Handhabungswiderstand <a class="header-anchor" href="#handhabungswiderstand" aria-label="Permalink to &quot;Handhabungswiderstand&quot;">​</a></h2><h3 id="der-quot-zu-coole-quot-athlet" tabindex="-1">Der &quot;zu coole&quot; Athlet <a class="header-anchor" href="#der-quot-zu-coole-quot-athlet" aria-label="Permalink to &quot;Der &amp;quot;zu coole&amp;quot; Athlet&quot;">​</a></h3><p><strong>Szenario:</strong> Ein Spieler verdreht die Augen bei einer Übung zur Verletzlichkeit.</p><p><strong>Strategie:</strong> Verbales Aikido (Ausrichten und Drehen)</p><p><strong>Skript:</strong></p><blockquote><p>„Ich sehe deine Reaktion, [Name]. Ehrlich gesagt, verstehe ich das. Über Gefühle zu sprechen, fühlt sich weich an. Aber die Situation ist unangenehm. Wenn wir mit dem Unbehagen in diesem Raum nicht umgehen können, trainieren wir auch nicht unsere Toleranz für das Unbehagen im Spiel. Kannst du mir 20 Minuten lang vertrauen?“</p></blockquote><h3 id="der-stille-teilnehmer" tabindex="-1">Der stille Teilnehmer <a class="header-anchor" href="#der-stille-teilnehmer" aria-label="Permalink to &quot;Der stille Teilnehmer&quot;">​</a></h3><p><strong>Szenario:</strong> Jemand hat seit 45 Minuten nicht gesprochen.</p><p><strong>Strategie:</strong> Einen Einstiegspunkt mit geringem Risiko schaffen</p><p><strong>Skript:</strong></p><blockquote><p>&quot;[Name], ich merke, dass du alles aufmerksam aufnimmst. Was spricht dich bisher besonders an? Und sei es nur ein Wort.&quot;</p></blockquote><h3 id="der-uberteiler" tabindex="-1">Der Überteiler <a class="header-anchor" href="#der-uberteiler" aria-label="Permalink to &quot;Der Überteiler&quot;">​</a></h3><p><strong>Szenario:</strong> Jemand dominiert mit langen Geschichten.</p><p><strong>Strategie:</strong> Sanfte Umleitung</p><p><strong>Skript:</strong></p><blockquote><p>„Vielen Dank dafür, [Name]. Ich möchte sicherstellen, dass jeder genügend Raum hat. Lassen wir jemanden zu Wort kommen, der seine Geschichte noch nicht geteilt hat.“</p></blockquote><h3 id="der-problemloser" tabindex="-1">Der Problemlöser <a class="header-anchor" href="#der-problemloser" aria-label="Permalink to &quot;Der Problemlöser&quot;">​</a></h3><p><strong>Szenario:</strong> Jemand versucht, die Probleme anderer zu lösen</p><p><strong>Strategie:</strong> Grundregeln verstärken</p><p><strong>Skript:</strong></p><blockquote><p>„Ich weiß es zu schätzen, dass Sie helfen wollen, aber denken Sie an unsere Regel: Zuhören und verstehen, nicht reparieren. [Sprecher], was brauchen Sie jetzt?“</p></blockquote><h2 id="materialliste" tabindex="-1">Materialliste <a class="header-anchor" href="#materialliste" aria-label="Permalink to &quot;Materialliste&quot;">​</a></h2><details class="details custom-block"><summary>Workshop-Materialien</summary><p><strong>Räumliche Gegebenheiten:</strong></p><ul><li>[ ] Stühle (6-8, keine Tische)</li><li>[ ] Boule und Cochonnet für die Mitte</li><li>[ ] Flipchart oder Whiteboard</li><li>[ ] Markierungen</li></ul><p><strong>Aktivitäten:</strong></p><ul><li>[ ] Haftnotizen (Check-in-Matrix)</li><li>[ ] Großformatiges Papier (Eisbergaktivität)</li><li>[ ] Arbeitsblätter des Benutzerhandbuchs</li><li>[ ] Papier und Stifte (Angst mit Hut)</li><li>[ ] Arbeitsblätter zum inneren Kritiker/Coach</li></ul><p><strong>Logistik:</strong></p><ul><li>[ ] Wasser für die Teilnehmer</li><li>[ ] Taschentücher (emotionale Arbeit!)</li><li>[ ] Timer (planmäßig einhalten)</li><li>[ ] Teilnehmerkontaktliste (für die Nachverfolgung)</li></ul></details><h2 id="koordinator-selbstfursorge" tabindex="-1">Koordinator Selbstfürsorge <a class="header-anchor" href="#koordinator-selbstfursorge" aria-label="Permalink to &quot;Koordinator Selbstfürsorge&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Du brauchst auch Unterstützung</p><p>Raum für Verletzlichkeit zu schaffen, ist emotional anspruchsvoll.</p><p><strong>Nach dem Workshop:</strong></p><ul><li>Nachbesprechung mit einem Kollegen oder Vorgesetzten</li><li>Schreibe in dein Tagebuch, was dir dabei in den Sinn kam.</li><li>Machen Sie einen Spaziergang oder eine körperliche Pause.</li><li>Nimm ihre Geschichten nicht mit nach Hause</li></ul></div><h2 id="wirkungsmessung" tabindex="-1">Wirkungsmessung <a class="header-anchor" href="#wirkungsmessung" aria-label="Permalink to &quot;Wirkungsmessung&quot;">​</a></h2><h3 id="unmittelbares-feedback" tabindex="-1">Unmittelbares Feedback <a class="header-anchor" href="#unmittelbares-feedback" aria-label="Permalink to &quot;Unmittelbares Feedback&quot;">​</a></h3><p>Fragen Sie zum Schluss:</p><ol><li>„Auf einer Skala von 1 bis 10, wie sicher haben Sie sich heute beim Teilen gefühlt?“</li><li>„Was würde die nächste Sitzung verbessern?“</li></ol><h3 id="langzeitverfolgung" tabindex="-1">Langzeitverfolgung <a class="header-anchor" href="#langzeitverfolgung" aria-label="Permalink to &quot;Langzeitverfolgung&quot;">​</a></h3><p>Nachkontrolle nach 2-4 Wochen:</p><ul><li>„Haben Sie irgendwelche Werkzeuge aus der Werkstatt benutzt?“</li><li>„Wie hat sich Ihre Beziehung zu Ihrem inneren Kritiker verändert?“</li><li>&quot;Was ist anders an Ihrer Wettbewerbsmentalität?&quot;</li></ul><h2 id="nachste-schritte" tabindex="-1">Nächste Schritte <a class="header-anchor" href="#nachste-schritte" aria-label="Permalink to &quot;Nächste Schritte&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Auf diesem Fundament aufbauen</p><p>Dieser Workshop ist Phase 1. Bitte beachten Sie Folgendes:</p><ul><li><strong>Folgetermine</strong> (online oder persönlich)</li><li><strong>Integration auf der Piste</strong> (siehe Leitfaden für die Trainingssitzung)</li><li><strong>Teamprotokolle</strong> (Benutzerhandbücher im Wettbewerb anwenden)</li><li><strong>Individuelle Check-ins</strong> (für Spieler, die mehr Unterstützung benötigen)</li></ul></div>',34)),a(p)])}]]);export{u as __pageData,g as default};
